import {avatarSVG,getSettings,escapeHTML as esc} from './settings.js';
import {lessonFor} from './coach-core.js';
export function renderReviewCoach(host,move,before,after,grade){const box=document.createElement('section');box.className='coach-inline';host.append(box);let step=0;const lessons=lessonFor(move,before,after,grade);function render(){const s=getSettings();box.innerHTML=`<div class="coach-inline-head">${avatarSVG(s)}<div><span class="eyebrow">RIVEDIAMOLA INSIEME</span><strong>${esc(s.coachName)}</strong></div></div>${(s.coachDetail==='compact'?lessons:[lessons[step]]).map(l=>`<p class="step-title">${esc(l.title)}</p><p>${esc(l.text)}</p>`).join('')}${s.coachDetail==='guided'?`<div class="step-controls"><button class="text-button" data-review-step="-1" ${step===0?'disabled':''}>← Indietro</button><span>${step+1} / 4</span><button class="secondary" data-review-step="1" ${step===3?'disabled':''}>Avanti →</button></div>`:''}`;box.querySelectorAll('[data-review-step]').forEach(b=>b.onclick=()=>{step=Math.max(0,Math.min(3,step+Number(b.dataset.reviewStep)));render()})}render()}
